using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Notifications;using Namaa.Api.Extensions;using Namaa.Application.Notifications.Commands.MarkNotificationRead;using Namaa.Application.Notifications.Queries.GetNotifications;namespace Namaa.Api.Controllers;[ApiController][Route("api/users/{userId:long}/notifications")]public sealed class NotificationsController(ISender sender):ControllerBase{[HttpGet]public async Task<IActionResult>GetAll(long userId,[FromQuery]bool? isRead,CancellationToken cancellationToken)=>(await sender.Send(new GetNotificationsQuery(userId,isRead),cancellationToken)).ToActionResult(this);[HttpPatch("{id:long}/read")]public async Task<IActionResult>MarkRead(long userId,long id,MarkNotificationReadRequest request,CancellationToken cancellationToken)=>(await sender.Send(new MarkNotificationReadCommand(userId,id,request.IsRead),cancellationToken)).ToActionResult(this);}
